# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MONDROS SONRASI KURULAN CEMİYETLER TABLOSU</text>\n  <!-- Kutu 1: Milli Cemiyetler -->\n  <rect x="18" y="42" width="222" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="129" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">MİLLÎ (YARARLI) CEMİYETLER</text>\n  <text x="28" y="86" font-size="10.8" fill="#14532d">• Kars İslam Şûrası (İlk kurulan)</text>\n  <text x="28" y="104" font-size="10.8" fill="#14532d">• Trakya-Paşaeli Müdâfaa-i Hukuk</text>\n  <text x="28" y="122" font-size="10.8" fill="#14532d">• İzmir Müdâfaa-i Hukuk &amp; Redd-i İlhak</text>\n  <text x="28" y="140" font-size="10.8" fill="#14532d">• Kilikyalılar (Çukurova / Adana)</text>\n  <text x="28" y="158" font-size="10.8" fill="#14532d">• Trabzon Muhâfaza-i Hukuk-ı Millîye</text>\n  <text x="28" y="176" font-size="10.8" fill="#14532d">• Doğu Anadolu Müdâfaa-i Hukuk</text>\n  <text x="28" y="194" font-size="10.8" fill="#14532d">• Millî Kongre (Dr. Esat Işık - Basın)</text>\n  <text x="28" y="212" font-size="10.8" fill="#14532d">• Karakol &amp; Anadolu Kadınları Cem.</text>\n  <text x="129" y="233" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Sivas Kongresi\'nde tek çatıda birleşti.</text>\n  <!-- Kutu 2: Azinlik Cemiyetleri -->\n  <rect x="252" y="42" width="212" height="202" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="358" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">AZINLIK CEMİYETLERİ</text>\n  <text x="264" y="88" font-size="11" font-weight="bold" fill="#7f1d1d">Rum Cemiyetleri:</text>\n  <text x="268" y="105" font-size="10.8" fill="#991b1b">• Mavri Mira &amp; Etniki Eterya</text>\n  <text x="268" y="122" font-size="10.8" fill="#991b1b">• Pontus Rum (Hrisantos, Germanos)</text>\n  <text x="264" y="146" font-size="11" font-weight="bold" fill="#7f1d1d">Ermeni Cemiyetleri:</text>\n  <text x="268" y="163" font-size="10.8" fill="#991b1b">• Hınçak ve Taşnaksutyun</text>\n  <text x="264" y="187" font-size="11" font-weight="bold" fill="#7f1d1d">Yahudi Cemiyetleri:</text>\n  <text x="268" y="204" font-size="10.8" fill="#991b1b">• Alyans İsrailit ve Makabi</text>\n  <text x="358" y="233" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">Amaç: Osmanlı topraklarını parçalamak.</text>\n  <!-- Kutu 3: Milli Varliga Dusman -->\n  <rect x="476" y="42" width="206" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="579" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">MİLLÎ VARLIĞA DÜŞMANLAR</text>\n  <text x="488" y="90" font-size="10.8" fill="#7c2d12">• Kürt Teâlî Cemiyeti</text>\n  <text x="488" y="110" font-size="10.8" fill="#7c2d12">• İslam Teâlî Cemiyeti</text>\n  <text x="488" y="130" font-size="10.8" fill="#7c2d12">• İngiliz Muhipleri Cemiyeti</text>\n  <text x="488" y="150" font-size="10.8" fill="#7c2d12">• Wilson Prensipleri Cemiyeti</text>\n  <text x="488" y="170" font-size="10.8" fill="#7c2d12">• Sulh ve Selâmet-i Osmaniye</text>\n  <text x="488" y="190" font-size="10.8" fill="#7c2d12">• Hürriyet ve İtilaf Fırkası</text>\n  <text x="579" y="216" text-anchor="middle" font-size="10.5" fill="#9a3412">Manda ve himayeyi veya</text>\n  <text x="579" y="232" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#c2410c">teslimiyetçi politikayı savundular.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SAMSUN\'A ÇIKIŞ, HAVZA VE AMASYA GENELGELERİ</text>\n  <!-- Sol: Samsun ve Havza -->\n  <rect x="25" y="42" width="300" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="175" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">SAMSUN VE HAVZA SÜRECİ</text>\n  <rect x="40" y="78" width="270" height="58" rx="6" fill="#dbeafe"/>\n  <text x="175" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">19 Mayıs 1919 — Samsun\'a Çıkış</text>\n  <text x="175" y="113" text-anchor="middle" font-size="11" fill="#1d4ed8">9. Ordu Müfettişliği &amp; Samsun Raporu:</text>\n  <text x="175" y="128" text-anchor="middle" font-size="10.5" fill="#1e3a8a">"Millet millî hâkimiyet ve bağımsızlık kararındadır."</text>\n  <rect x="40" y="146" width="270" height="84" rx="6" fill="#dbeafe"/>\n  <text x="175" y="164" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">28 Mayıs 1919 — Havza Genelgesi</text>\n  <text x="48" y="182" font-size="10.8" fill="#1e3a8a">• İşgalleri protesto mitingleri düzenlenmesi.</text>\n  <text x="48" y="198" text-anchor="middle" font-size="10.8" fill="#1e3a8a" dx="115">• Hristiyan halka kötü muamele edilmemesi.</text>\n  <text x="175" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Önemi: Millî bilinci uyandıran ilk genelge.</text>\n  <!-- Sag: Amasya Genelgesi -->\n  <rect x="345" y="42" width="330" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="510" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">AMASYA GENELGESİ (22 HAZİRAN 1919)</text>\n  <text x="360" y="88" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Gerekçe 1:</tspan> Vatanın bütünlüğü, milletin istiklali tehlikededir.</text>\n  <text x="360" y="108" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Gerekçe 2:</tspan> İstanbul Hükûmeti görevini yapamamaktadır.</text>\n  <rect x="360" y="120" width="300" height="46" rx="6" fill="#fde68a" stroke="#f59e0b"/>\n  <text x="510" y="138" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">AMAÇ VE YÖNTEM (İhtilal Bildirisi):</text>\n  <text x="510" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">"Milletin istiklalini yine milletin azim ve kararı kurtaracaktır."</text>\n  <text x="360" y="186" font-size="11.2" fill="#78350f">• Temsil Heyeti fikri ve Sivas Kongresi çağrısı yapıldı.</text>\n  <text x="360" y="206" font-size="11.2" fill="#78350f">• Onaylayanlar: M. Kemal, Rauf, Ali Fuat, Refet, K. Karabekir.</text>\n  <text x="360" y="226" font-size="11.2" font-weight="bold" fill="#b45309">• İlk kez "millî egemenlik" kavramına üstü kapalı vurgu!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ERZURUM KONGRESİ, SİVAS KONGRESİ VE AMASYA GÖRÜŞMELERİ</text>\n  <!-- Kutu 1: Erzurum Kongresi -->\n  <rect x="18" y="42" width="215" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ERZURUM KONGRESİ</text>\n  <text x="125" y="80" text-anchor="middle" font-size="10.5" fill="#7e22ce">(23 Temmuz - 7 Ağustos 1919)</text>\n  <text x="28" y="102" font-size="10.8" font-weight="bold" fill="#581c87">• Toplanışı bölgesel, kararları ulusal.</text>\n  <text x="28" y="122" font-size="10.8" fill="#581c87">• "Millî sınırlar içinde vatan bir</text>\n  <text x="36" y="136" font-size="10.8" fill="#581c87">bütündür, parçalanamaz." (İlk kez)</text>\n  <text x="28" y="156" font-size="10.8" fill="#581c87">• Manda ve himaye İLK KEZ reddedildi.</text>\n  <text x="28" y="176" font-size="10.8" fill="#581c87">• 9 kişilik Temsil Heyeti kuruldu.</text>\n  <text x="28" y="196" font-size="10.8" fill="#581c87">• Kuvâ-yı Millîye\'yi etkin, millî</text>\n  <text x="36" y="210" font-size="10.8" fill="#581c87">iradeyi hâkim kılmak esastır.</text>\n  <!-- Kutu 2: Sivas Kongresi -->\n  <rect x="245" y="42" width="220" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="355" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SİVAS KONGRESİ</text>\n  <text x="355" y="80" text-anchor="middle" font-size="10.5" fill="#15803d">(4 - 11 Eylül 1919)</text>\n  <text x="256" y="102" font-size="10.8" font-weight="bold" fill="#14532d">• Toplanışı ve kararları ULUSAL.</text>\n  <text x="256" y="122" font-size="10.8" fill="#14532d">• Manda ve himaye KESİN reddedildi.</text>\n  <text x="256" y="142" font-size="10.8" fill="#14532d">• Tüm cemiyetler "Anadolu ve Rumeli</text>\n  <text x="264" y="156" font-size="10.8" fill="#14532d">Müdâfaa-i Hukuk" adıyla birleşti.</text>\n  <text x="256" y="176" font-size="10.8" fill="#14532d">• İrade-i Millîye gazetesi çıkarıldı.</text>\n  <text x="256" y="196" font-size="10.8" fill="#14532d">• Ali Fuat Paşa Batı Cephesi\'ne atandı</text>\n  <text x="264" y="210" font-size="10.8" font-weight="bold" fill="#15803d">(Yürütme yetkisi kullanıldı).</text>\n  <!-- Kutu 3: Amasya Gorusmeleri -->\n  <rect x="477" y="42" width="205" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="579" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">AMASYA GÖRÜŞMELERİ</text>\n  <text x="579" y="80" text-anchor="middle" font-size="10.5" fill="#c2410c">(20 - 22 Ekim 1919)</text>\n  <text x="488" y="102" font-size="10.8" fill="#7c2d12">• Damat Ferit Hükûmeti düştü (İlk</text>\n  <text x="496" y="116" font-size="10.8" fill="#7c2d12">siyasi zafer), Ali Rıza Paşa geldi.</text>\n  <text x="488" y="138" font-size="10.8" fill="#7c2d12">• Bahriye Nazırı Salih Paşa ile</text>\n  <text x="496" y="152" font-size="10.8" fill="#7c2d12">Mustafa Kemal Paşa görüştü.</text>\n  <text x="488" y="174" font-size="10.8" fill="#7c2d12">• Mebusan Meclisi açılması kabul edildi.</text>\n  <rect x="488" y="188" width="183" height="44" rx="6" fill="#ffedd5"/>\n  <text x="579" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9a3412">Önemi: İstanbul Hükûmeti, Temsil</text>\n  <text x="579" y="222" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9a3412">Heyeti\'ni RESMEN tanıdı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
